+            assertTrue(find(Dialog.class).single().isOpened());
+            click("Keep editing");
+            if (label.equals("Email")) test(email()).clear();
+            else if (label.equals("Message")) test(message()).clear();
+            else test(find(TextField.class).withLabel(label).single()).clear();
+        }
+        UI.getCurrent().navigate("about");
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertFalse(find(Dialog.class).exists());
+    }
